function altVerifyEmail($email)
{
	//VER 1.0
	list($userName, $mailDomain) = split("@", $email);
	if (checkdnsrr($mailDomain, "MX")) { return "OK"; } 
	else { return "INVALID"; }
}

function missingnos($str){
	//VER 1.0
	$test=true;
	$reqchars="1234567890";
	for ($count=0; $count<strlen($reqchars); $count++)
	{
		if (strpos($str, $reqchars[$count])!==false)
		$test=false;
	}
	return $test;
}

